#include <bits/stdc++.h>
using namespace std;

class AntiPalindrome {
public:
    void solve(int testNumber, istream& in, ostream& out) {
        int N;
        in >> N;
        vector<int> countLetters(26, 0);
        int totalMoves = 0;
        string s;
        in >> s;
        vector<int> costs(N);
        int totalCost = 0;
        for (int i = 0; i < N; i++) {
            in >> costs[i];
            totalCost += costs[i];
        }
        for (int i = 0; i < N / 2; i++) {
            if (s[i] == s[N - i - 1]) {
                countLetters[s[i] - 'a']++;
                totalMoves++;
                totalCost -= min(costs[i], costs[N - i - 1]);
            }
        }
        for (int i = 0; i < 26; i++) {
            if (countLetters[i] > totalMoves / 2) {
                int excess = countLetters[i] * 2 - totalMoves;
                vector<int> positions;
                for (int j = 0; j < N / 2; j++) {
                    if (s[j] != s[N - j - 1]) {
                        if (s[j] - 'a' != i && s[N - j - 1] - 'a' != i) {
                            positions.push_back(min(costs[j], costs[N - j - 1]));
                        }
                    }
                }
                sort(positions.begin(), positions.end());
                for (int j = 0; j < min(excess, (int)positions.size()); j++) {
                    totalCost -= positions[j];
                }
            }
        }
        out << totalCost << "\n";
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    AntiPalindrome ap;
    ap.solve(1, cin, cout);
    return 0;
}

